// Temporary measurement-only observer for the original Now SQL call.
type NowSQLObserver interface {
	BeginNowSQL() time.Time
	EndNowSQL(time.Time, error)
}
type nowSQLObserverKey struct{}
func WithNowSQLObserver(ctx context.Context, observer NowSQLObserver) context.Context {
	return context.WithValue(ctx, nowSQLObserverKey{}, observer)
}

